from pathlib import Path

service_path = Path('AgentPortal/Services/LegendFounderAiConversationService.cs')
controller_path = Path('AgentPortal/Controllers/LegendFounderAiController.cs')
test_path = Path('AgentPortal.Tests/LegendFounderAiProviderResilienceTests.cs')


def once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected one match, found {count}')
    return text.replace(old, new, 1)

service = service_path.read_text()

service = once(
    service,
    '    private const int MaximumRetainedContextCharacters = 16_000;\n',
    '    private const int MaximumRetainedContextCharacters = 16_000;\n'
    '    private const int MinimumProviderAttemptWindowSeconds = 3;\n'
    '    private const int MaximumProviderCooldownSeconds = 300;\n'
    '    private static readonly object ProviderCooldownSync = new();\n'
    '    private static DateTimeOffset _providerNotBeforeUtc = DateTimeOffset.MinValue;\n',
    'resilience constants')

old_loop = '''        for (var attempt = 1;\n             attempt <= 2;\n             attempt++)\n        {\n            var attemptRemaining =\n                providerBudget -\n                providerClock.Elapsed;\n\n            if (attemptRemaining <=\n                TimeSpan.FromSeconds(1))\n            {\n                throw new OperationCanceledException();\n            }\n'''
new_loop = '''        var attempt = 0;\n\n        while (true)\n        {\n            attempt++;\n\n            await WaitForProviderCooldownAsync(\n                providerBudget,\n                providerClock,\n                cancellationToken);\n\n            var attemptRemaining =\n                providerBudget -\n                providerClock.Elapsed;\n\n            if (attemptRemaining <=\n                TimeSpan.FromSeconds(\n                    MinimumProviderAttemptWindowSeconds))\n            {\n                throw new OperationCanceledException();\n            }\n'''
service = once(service, old_loop, new_loop, 'provider loop')

old_retry = '''            if (transient &&\n                attempt < 2)\n            {\n                var retryAfter =\n                    response.Headers\n                        .RetryAfter?\n                        .Delta;\n\n                var delay =\n                    retryAfter is null\n                        ? TimeSpan.FromSeconds(1)\n                        : TimeSpan.FromSeconds(\n                            Math.Clamp(\n                                retryAfter.Value.TotalSeconds,\n                                1,\n                                5));\n\n                await Task.Delay(\n                    delay,\n                    providerAttempt.Token);\n\n                continue;\n            }\n'''
new_retry = '''            if (transient)\n            {\n                var delay =\n                    ResolveProviderRetryDelay(\n                        response,\n                        attempt);\n\n                ExtendProviderCooldown(delay);\n\n                var remainingAfterResponse =\n                    providerBudget -\n                    providerClock.Elapsed;\n\n                if (remainingAfterResponse >\n                    TimeSpan.FromSeconds(\n                        MinimumProviderAttemptWindowSeconds))\n                {\n                    var maximumDelay =\n                        remainingAfterResponse -\n                        TimeSpan.FromSeconds(\n                            MinimumProviderAttemptWindowSeconds);\n\n                    var boundedDelay =\n                        delay <= maximumDelay\n                            ? delay\n                            : maximumDelay;\n\n                    if (boundedDelay > TimeSpan.Zero)\n                    {\n                        _logger.LogWarning(\n                            "LEGEND Founder AI provider transient rejection. " +\n                            "HTTP={StatusCode} Attempt={Attempt} RetryDelayMs={RetryDelayMs} " +\n                            "RequestReset={RequestReset} TokenReset={TokenReset}",\n                            (int)response.StatusCode,\n                            attempt,\n                            (long)Math.Ceiling(boundedDelay.TotalMilliseconds),\n                            GetProviderHeader(response, "x-ratelimit-reset-requests") ?? "unavailable",\n                            GetProviderHeader(response, "x-ratelimit-reset-tokens") ?? "unavailable");\n\n                        await Task.Delay(\n                            boundedDelay,\n                            cancellationToken);\n\n                        continue;\n                    }\n                }\n            }\n'''
service = once(service, old_retry, new_retry, 'provider retry')

old_request_id = '''            var providerRequestId =\n                response.Headers.TryGetValues(\n                    "x-request-id",\n                    out var providerRequestIds)\n                    ? providerRequestIds.FirstOrDefault()\n                    : null;\n'''
new_request_id = '''            var providerRequestId =\n                GetProviderHeader(\n                    response,\n                    "x-request-id");\n'''
service = once(service, old_request_id, new_request_id, 'provider request id')

insert_at = '''    private static ValueTask ReportProgressAsync(\n'''
helpers = '''    private static async Task WaitForProviderCooldownAsync(\n        TimeSpan providerBudget,\n        Stopwatch providerClock,\n        CancellationToken cancellationToken)\n    {\n        TimeSpan delay;\n\n        lock (ProviderCooldownSync)\n        {\n            delay =\n                _providerNotBeforeUtc -\n                DateTimeOffset.UtcNow;\n        }\n\n        if (delay <= TimeSpan.Zero)\n            return;\n\n        var maximumDelay =\n            providerBudget -\n            providerClock.Elapsed -\n            TimeSpan.FromSeconds(\n                MinimumProviderAttemptWindowSeconds);\n\n        if (maximumDelay <= TimeSpan.Zero)\n            throw new OperationCanceledException();\n\n        if (delay > maximumDelay)\n            delay = maximumDelay;\n\n        await Task.Delay(delay, cancellationToken);\n    }\n\n    private static void ExtendProviderCooldown(\n        TimeSpan delay)\n    {\n        if (delay <= TimeSpan.Zero)\n            return;\n\n        var maximum =\n            TimeSpan.FromSeconds(\n                MaximumProviderCooldownSeconds);\n\n        if (delay > maximum)\n            delay = maximum;\n\n        var candidate =\n            DateTimeOffset.UtcNow + delay;\n\n        lock (ProviderCooldownSync)\n        {\n            if (candidate > _providerNotBeforeUtc)\n                _providerNotBeforeUtc = candidate;\n        }\n    }\n\n    private static TimeSpan ResolveProviderRetryDelay(\n        HttpResponseMessage response,\n        int attempt)\n    {\n        var retryAfter =\n            response.Headers.RetryAfter?.Delta;\n\n        if (retryAfter is null &&\n            response.Headers.RetryAfter?.Date is { } retryDate)\n        {\n            var datedDelay =\n                retryDate - DateTimeOffset.UtcNow;\n\n            if (datedDelay > TimeSpan.Zero)\n                retryAfter = datedDelay;\n        }\n\n        var resetDelay =\n            ReadLongestRateLimitReset(response);\n\n        var providerDelay =\n            retryAfter is null\n                ? resetDelay\n                : resetDelay is null || retryAfter >= resetDelay\n                    ? retryAfter\n                    : resetDelay;\n\n        if (providerDelay is { } hinted &&\n            hinted > TimeSpan.Zero)\n        {\n            return hinted > TimeSpan.FromSeconds(MaximumProviderCooldownSeconds)\n                ? TimeSpan.FromSeconds(MaximumProviderCooldownSeconds)\n                : hinted;\n        }\n\n        var exponent = Math.Min(Math.Max(attempt - 1, 0), 6);\n        var seconds = Math.Pow(2, exponent) + Random.Shared.NextDouble() * 0.5;\n        return TimeSpan.FromSeconds(seconds);\n    }\n\n    private static TimeSpan? ReadLongestRateLimitReset(\n        HttpResponseMessage response)\n    {\n        TimeSpan? longest = null;\n\n        foreach (var name in new[]\n                 {\n                     "x-ratelimit-reset-requests",\n                     "x-ratelimit-reset-tokens"\n                 })\n        {\n            var raw = GetProviderHeader(response, name);\n            if (!TryParseProviderDuration(raw, out var parsed))\n                continue;\n\n            if (longest is null || parsed > longest.Value)\n                longest = parsed;\n        }\n\n        return longest;\n    }\n\n    private static bool TryParseProviderDuration(\n        string? raw,\n        out TimeSpan duration)\n    {\n        duration = TimeSpan.Zero;\n        if (string.IsNullOrWhiteSpace(raw))\n            return false;\n\n        var value = raw.Trim();\n        var index = 0;\n        double totalMilliseconds = 0;\n\n        while (index < value.Length)\n        {\n            var numberStart = index;\n            while (index < value.Length &&\n                   (char.IsDigit(value[index]) || value[index] == '.'))\n            {\n                index++;\n            }\n\n            if (numberStart == index ||\n                !double.TryParse(\n                    value[numberStart..index],\n                    System.Globalization.NumberStyles.Float,\n                    System.Globalization.CultureInfo.InvariantCulture,\n                    out var amount))\n            {\n                return false;\n            }\n\n            string unit;\n            if (value.AsSpan(index).StartsWith("ms", StringComparison.OrdinalIgnoreCase))\n            {\n                unit = "ms";\n                index += 2;\n            }\n            else if (index < value.Length)\n            {\n                unit = char.ToLowerInvariant(value[index]).ToString();\n                index++;\n            }\n            else\n            {\n                return false;\n            }\n\n            totalMilliseconds += unit switch\n            {\n                "ms" => amount,\n                "s" => amount * 1_000d,\n                "m" => amount * 60_000d,\n                "h" => amount * 3_600_000d,\n                _ => double.NaN\n            };\n\n            if (double.IsNaN(totalMilliseconds))\n                return false;\n        }\n\n        if (totalMilliseconds <= 0 || double.IsInfinity(totalMilliseconds))\n            return false;\n\n        duration = TimeSpan.FromMilliseconds(totalMilliseconds);\n        return true;\n    }\n\n    private static string? GetProviderHeader(\n        HttpResponseMessage response,\n        string name) =>\n        response.Headers.TryGetValues(name, out var values)\n            ? values.FirstOrDefault()\n            : null;\n\n'''
service = once(service, insert_at, helpers + insert_at, 'provider helpers')
service_path.write_text(service)

controller = controller_path.read_text()
controller = once(
    controller,
    '            "timeout" => StatusCodes.Status504GatewayTimeout,\n            "provider_http" or "transport" or "provider_json" => StatusCodes.Status502BadGateway,\n',
    '            "timeout" => StatusCodes.Status504GatewayTimeout,\n            "provider_http" when result.ProviderStatusCode == StatusCodes.Status429TooManyRequests => StatusCodes.Status429TooManyRequests,\n            "provider_http" when result.ProviderStatusCode == StatusCodes.Status503ServiceUnavailable => StatusCodes.Status503ServiceUnavailable,\n            "provider_http" when result.ProviderStatusCode is StatusCodes.Status408RequestTimeout or StatusCodes.Status504GatewayTimeout => StatusCodes.Status504GatewayTimeout,\n            "provider_http" or "transport" or "provider_json" => StatusCodes.Status502BadGateway,\n',
    'provider status mapping')
controller_path.write_text(controller)

test_path.write_text('''using System.Net;\nusing System.Reflection;\nusing AgentPortal.Controllers;\nusing AgentPortal.Services;\nusing Microsoft.AspNetCore.Http;\nusing Xunit;\n\nnamespace AgentPortal.Tests;\n\npublic sealed class LegendFounderAiProviderResilienceTests\n{\n    [Theory]\n    [InlineData(429, StatusCodes.Status429TooManyRequests)]\n    [InlineData(503, StatusCodes.Status503ServiceUnavailable)]\n    [InlineData(504, StatusCodes.Status504GatewayTimeout)]\n    [InlineData(408, StatusCodes.Status504GatewayTimeout)]\n    [InlineData(400, StatusCodes.Status502BadGateway)]\n    public void ControllerMapsProviderFailuresTruthfully(int providerStatus, int expectedStatus)\n    {\n        var method = typeof(LegendFounderAiController).GetMethod("MapStatus", BindingFlags.NonPublic | BindingFlags.Static);\n        Assert.NotNull(method);\n        var result = LegendFounderAiChatResponse.Failure("provider", "provider_http", providerStatus, "req_test");\n        Assert.Equal(expectedStatus, Assert.IsType<int>(method!.Invoke(null, new object[] { result })));\n    }\n\n    [Fact]\n    public void RetryPolicyHonorsProviderRetryAfterBeyondLegacyFiveSecondCap()\n    {\n        var method = typeof(LegendFounderAiConversationService).GetMethod("ResolveProviderRetryDelay", BindingFlags.NonPublic | BindingFlags.Static);\n        Assert.NotNull(method);\n        using var response = new HttpResponseMessage(HttpStatusCode.TooManyRequests);\n        response.Headers.RetryAfter = new System.Net.Http.Headers.RetryConditionHeaderValue(TimeSpan.FromSeconds(12));\n        var delay = Assert.IsType<TimeSpan>(method!.Invoke(null, new object[] { response, 1 }));\n        Assert.True(delay >= TimeSpan.FromSeconds(11.9));\n    }\n\n    [Theory]\n    [InlineData("250ms", 0.25)]\n    [InlineData("2s", 2.0)]\n    [InlineData("1m30s", 90.0)]\n    public void RetryPolicyParsesProviderResetDurations(string raw, double expectedSeconds)\n    {\n        var method = typeof(LegendFounderAiConversationService).GetMethod("TryParseProviderDuration", BindingFlags.NonPublic | BindingFlags.Static);\n        Assert.NotNull(method);\n        var args = new object?[] { raw, null };\n        Assert.True(Assert.IsType<bool>(method!.Invoke(null, args)));\n        var duration = Assert.IsType<TimeSpan>(args[1]);\n        Assert.InRange(duration.TotalSeconds, expectedSeconds - 0.001, expectedSeconds + 0.001);\n    }\n}\n''')

print('Applied LEGEND Founder AI provider resilience repair.')
